index 0000000..cf355a5
--- /dev/null
+++ b/crates/fdb-gateway/tests/schema_routes.rs
@@ -0,0 +1,227 @@
+//! Route tests for `/schema/v1` (p17-c004, FFS-001 §8 Phase 3 gate).
+//!
+//! Layered gating so each case runs in the richest environment available and
+//! skips cleanly below it:
+//! - `DATABASE_URL` (+ migration 0015 artifacts) — needed by every case
+//!   (`SchemaApiState` holds a live `StateManager`).
+//! - Real keys (`FLINT_SERVICE_ROLE_KEY`, `FLINT_ANON_KEY`, served
+//!   `FLINT_GATE_JWKS_URL`, issuer/audience) — needed by the role-matrix and
+//!   success-path cases, per FFS-001 §9: use the actual credentials, not
+//!   synthetic tokens.
+//!
+//! Matrix (each its own test): 503 disabled (pinned as 503, NOT 404), 401 no
+//! header, 401 bad signature, 403 anon role, 403 reserved namespace, 403
+//! non-allowlisted namespace, 200 plan, 200 apply → table exists, 200 replay
+//! alreadyApplied, 409 drift.
+
+#![allow(clippy::expect_used)]
+
+use axum::http::StatusCode;
+use axum::Router;
+use fdb_gateway_test_support::*;
+use tower::ServiceExt;
+
+/// Everything shared by the cases lives in a support module compiled into
+/// this test binary.
+#[path = "support/schema_routes_support.rs"]
+mod fdb_gateway_test_support;
+
+#[tokio::test]
+async fn disabled_deployment_returns_503_not_404() {
+    let Some(env) = TestEnv::database_only().await else { return };
+    let router = env.router_disabled();
+    for (method, uri) in [("GET", "/schema/v1/status"), ("POST", "/schema/v1/plan"), ("POST", "/schema/v1/apply")] {
+        let response = router
+            .clone()
+            .oneshot(request(method, uri, None, b"{}"))
+            .await
+            .expect("infallible");
+        assert_eq!(
+            response.status(),
+            StatusCode::SERVICE_UNAVAILABLE,
+            "{method} {uri} must be 503 when disabled — a 404 would mean the route was not mounted"
+        );
+        let body = body_json(response).await;
+        assert_eq!(body["error"], "schema provisioning is not enabled");
+    }
+}
+
+#[tokio::test]
+async fn missing_authorization_header_is_401() {
+    let Some(env) = TestEnv::database_only().await else { return };
+    let router = env.router_enabled(&["p17c004_nsx"]);
+    let response = router
+        .oneshot(request("POST", "/schema/v1/plan", None, b"{}"))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
+}
+
+#[tokio::test]
+async fn garbage_bearer_is_401() {
+    let Some(env) = TestEnv::database_only().await else { return };
+    let router = env.router_enabled(&["p17c004_nsx"]);
+    let response = router
+        .oneshot(request("POST", "/schema/v1/plan", Some("not-a-jwt"), b"{}"))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::UNAUTHORIZED);
+}
+
+#[tokio::test]
+async fn anon_key_is_403() {
+    let Some(env) = TestEnv::with_keys().await else { return };
+    let Some(anon) = env.anon_key.clone() else {
+        eprintln!("skipping: FLINT_ANON_KEY not set");
+        return;
+    };
+    let router = env.router_enabled(&["p17c004_nsx"]);
+    let response = router
+        .oneshot(request("POST", "/schema/v1/plan", Some(&anon), b"{}"))
+        .await
+        .expect("infallible");
+    assert_eq!(
+        response.status(),
+        StatusCode::FORBIDDEN,
+        "the publishable anon key must never reach a provisioning route"
+    );
+}
+
+#[tokio::test]
+async fn reserved_namespace_is_403_even_when_allowlisted() {
+    let Some(env) = TestEnv::with_keys().await else { return };
+    // Operator misconfiguration: reserved names must lose to the hard refusal.
+    let router = env.router_enabled(&["flint_meta"]);
+    let response = router
+        .oneshot(request(
+            "POST",
+            "/schema/v1/plan",
+            Some(&env.service_key),
+            spec_body("flint_meta", "t").as_bytes(),
+        ))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::FORBIDDEN);
+    let body = body_json(response).await;
+    assert!(body["error"].as_str().expect("error string").contains("reserved"));
+}
+
+#[tokio::test]
+async fn non_allowlisted_namespace_is_403() {
+    let Some(env) = TestEnv::with_keys().await else { return };
+    let router = env.router_enabled(&["p17c004_other"]);
+    let response = router
+        .oneshot(request(
+            "POST",
+            "/schema/v1/plan",
+            Some(&env.service_key),
+            spec_body("p17c004_notlisted", "t").as_bytes(),
+        ))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::FORBIDDEN);
+}
+
+#[tokio::test]
+async fn plan_apply_replay_and_drift_full_cycle() {
+    let Some(env) = TestEnv::with_keys().await else { return };
+    let ns = "p17c004_cycle";
+    env.reset_namespace(ns).await;
+    let router: Router = env.router_enabled(&[ns]);
+
+    // 200 plan
+    let response = router
+        .clone()
+        .oneshot(request(
+            "POST",
+            "/schema/v1/plan",
+            Some(&env.service_key),
+            spec_body(ns, "watch").as_bytes(),
+        ))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::OK, "plan must succeed");
+    let plan = body_json(response).await;
+    let hash = plan["planHash"].as_str().expect("planHash").to_owned();
+    assert_eq!(plan["noop"], false);
+    assert!(plan["ddl"].as_str().expect("ddl").contains("FORCE ROW LEVEL SECURITY"));
+
+    // 200 apply → table exists on a fresh connection
+    let apply_body = format!(r#"{{"planHash":"{hash}"}}"#);
+    let response = router
+        .clone()
+        .oneshot(request("POST", "/schema/v1/apply", Some(&env.service_key), apply_body.as_bytes()))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::OK, "apply must succeed");
+    let applied = body_json(response).await;
+    assert_eq!(applied["applied"], true);
+    assert_eq!(applied["alreadyApplied"], false);
+    assert_eq!(applied["restartRequired"], true);
+    assert!(env.table_exists(ns, "watch").await, "table must exist after apply");
+
+    // 200 replay → alreadyApplied
+    let response = router
+        .clone()
+        .oneshot(request("POST", "/schema/v1/apply", Some(&env.service_key), apply_body.as_bytes()))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::OK);
+    assert_eq!(body_json(response).await["alreadyApplied"], true);
+
+    // 409 drift: fresh plan for a second table, then mutate the namespace out
+    // of band before applying.
+    let response = router
+        .clone()
+        .oneshot(request(
+            "POST",
+            "/schema/v1/plan",
+            Some(&env.service_key),
+            spec_body(ns, "drifty").as_bytes(),
+        ))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::OK);
+    let hash2 = body_json(response).await["planHash"].as_str().expect("planHash").to_owned();
+    env.create_out_of_band_table(ns, "drifty").await;
+    let response = router
+        .clone()
+        .oneshot(request(
+            "POST",
+            "/schema/v1/apply",
+            Some(&env.service_key),
+            format!(r#"{{"planHash":"{hash2}"}}"#).as_bytes(),
+        ))
+        .await
+        .expect("infallible");
+    assert_eq!(
+        response.status(),
+        StatusCode::CONFLICT,
+        "out-of-band schema drift must refuse with 409"
+    );
+
+    // Unknown hash → 404
+    let response = router
+        .clone()
+        .oneshot(request(
+            "POST",
+            "/schema/v1/apply",
+            Some(&env.service_key),
+            br#"{"planHash":"sha256:doesnotexist"}"#,
+        ))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::NOT_FOUND);
+
+    // status reflects the apply
+    let response = router
+        .oneshot(request("GET", "/schema/v1/status", Some(&env.service_key), b""))
+        .await
+        .expect("infallible");
+    assert_eq!(response.status(), StatusCode::OK);
+    let status = body_json(response).await;
+    assert_eq!(status["enabled"], true);
+    assert_eq!(status["lastApply"]["status"], "applied");
+
+    env.reset_namespace(ns).await;
+}
diff --git a/crates/fdb-gateway/tests/support/schema_routes_support.rs b/crates/fdb-gateway/tests/support/schema_routes_support.rs
new file mode 100644
index 0000000..09d4a18
--- /dev/null
+++ b/crates/fdb-gateway/tests/support/schema_routes_support.rs
@@ -0,0 +1,217 @@
+//! Shared harness for the `/schema/v1` route tests (p17-c004).
+//!
+//! Builds the real `SchemaApiState` — live `StateManager` (mirroring
+//! `bootstrap.rs`, same construction as `gateway_startup_live_pg.rs`), real
+//! `PgProvisioner` — and drives the actual handlers via
+//! `tower::ServiceExt::oneshot`. No mocks on the path under test.
+
+#![allow(clippy::expect_used)]
+
+use std::sync::Arc;
+
+use axum::body::Body;
+use axum::http::Request;
+use axum::routing::{get, post};
+use axum::Router;
+use fdb_gateway::schema_api::{self, SchemaApiState};
+use fdb_postgres::{PgProvisioner, PgRest};
+use fdb_reflection::{MutationGates, ReflectionEngine, StateManager};
+use futures::{stream, StreamExt};
+use sqlx::PgPool;
+use tokio_postgres::NoTls;
+
+pub fn env_nonempty(key: &str) -> Option<String> {
+    std::env::var(key).ok().filter(|v| !v.is_empty())
+}
+
+pub struct TestEnv {
+    pub db_url: String,
+    pub service_key: String,
+    pub anon_key: Option<String>,
+    pub state_manager: Arc<StateManager>,
+}
+
+impl TestEnv {
+    /// Gate on `DATABASE_URL` + migration-0015 artifacts; `service_key` is a
+    /// placeholder in this tier (auth-failure cases only).
+    pub async fn database_only() -> Option<Self> {
+        let db_url = env_nonempty("DATABASE_URL").or_else(|| {
+            eprintln!("skipping: DATABASE_URL not set");
+            None
+        })?;
+
+        let admin = admin_client(&db_url).await;
+        let ledger: bool = admin
+            .query_one(
+                "SELECT to_regclass('flint_schema.provision_ledger') IS NOT NULL",
+                &[],
+            )
+            .await
+            .expect("regclass query")
+            .get(0);
+        if !ledger {
+            eprintln!("skipping: migration 0015 artifacts absent");
+            return None;
+        }
+
+        let pool = PgPool::connect(&db_url).await.expect("sqlx pool connect");
+        let rest_pool = {
+            let mut cfg = deadpool_postgres::Config::new();
+            cfg.url = Some(db_url.clone());
+            cfg.create_pool(
+                Some(deadpool_postgres::Runtime::Tokio1),
+                tokio_postgres::NoTls,
+            )
+            .expect("rest pool create")
+        };
+        let executor: Arc<dyn fdb_ports::SqlExecutor> = Arc::new(PgRest::new(rest_pool));
+        let engine = ReflectionEngine::new(pool);
+        let empty_factory = Arc::new(|_spec, _meta, _who| {
+            stream::empty::<async_graphql::Result<async_graphql::Value>>().boxed()
+        });
+        let state_manager = Arc::new(
+            StateManager::new_with_gates(
+                engine,
+                executor,
+                db_url.clone(),
+                MutationGates::default(),
+                empty_factory,
+            )
+            .await
+            .expect("initial schema compile"),
+        );
+
+        Some(Self {
+            db_url,
+            service_key: "unset".to_owned(),
+            anon_key: None,
+            state_manager,
+        })
+    }
+
+    /// Additionally gate on the real Sansaba keys + a served JWKS
+    /// (FFS-001 §9: real credentials, not synthetic tokens).
+    pub async fn with_keys() -> Option<Self> {
+        let mut env = Self::database_only().await?;
+        let (Some(service_key), Some(_jwks)) = (
+            env_nonempty("FLINT_SERVICE_ROLE_KEY"),
+            env_nonempty("FLINT_GATE_JWKS_URL"),
+        ) else {
+            eprintln!("skipping: FLINT_SERVICE_ROLE_KEY / FLINT_GATE_JWKS_URL not set");
+            return None;
+        };
+        env.service_key = service_key;
+        env.anon_key = env_nonempty("FLINT_ANON_KEY");
+        Some(env)
+    }
+
+    fn router_with(&self, provisioner: Option<Arc<dyn fdb_ports::SchemaProvisioner>>, namespaces: &[&str]) -> Router {
+        let state = SchemaApiState {
+            provisioner,
+            namespaces: Arc::new(namespaces.iter().map(|s| (*s).to_owned()).collect()),
+            state_manager: Arc::clone(&self.state_manager),
+        };
+        Router::new()
+            .route("/schema/v1/plan", post(schema_api::plan::plan))
+            .route("/schema/v1/apply", post(schema_api::apply::apply))
+            .route("/schema/v1/status", get(schema_api::status::status))
+            .with_state(state)
+    }
+
+    pub fn router_disabled(&self) -> Router {
+        self.router_with(None, &[])
+    }
+
+    pub fn router_enabled(&self, namespaces: &[&str]) -> Router {
+        let provisioner =
+            PgProvisioner::from_url(&self.db_url).expect("provisioner pool from DATABASE_URL");
+        self.router_with(Some(Arc::new(provisioner)), namespaces)
+    }
+
+    pub async fn reset_namespace(&self, ns: &str) {
+        let admin = admin_client(&self.db_url).await;
+        admin
+            .batch_execute(&format!("DROP SCHEMA IF EXISTS {ns} CASCADE"))
+            .await
+            .expect("drop fixture schema");
+        admin
+            .execute(
+                "DELETE FROM flint_schema.provision_ledger WHERE namespace = $1",
+                &[&ns],
+            )
+            .await
+            .expect("clear fixture ledger rows");
+        admin
+            .batch_execute(&format!(
+                "CREATE SCHEMA {ns}; GRANT USAGE, CREATE ON SCHEMA {ns} TO flint_provisioner;"
+            ))
+            .await
+            .expect("create granted fixture schema");
+    }
+
+    pub async fn table_exists(&self, ns: &str, table: &str) -> bool {
+        let admin = admin_client(&self.db_url).await;
+        admin
+            .query_one(
+                &format!("SELECT to_regclass('{ns}.{table}') IS NOT NULL"),
+                &[],
+            )
+            .await
+            .expect("regclass query")
+            .get(0)
+    }
+
+    /// Simulate out-of-band drift: create the table behind the API's back.
+    pub async fn create_out_of_band_table(&self, ns: &str, table: &str) {
+        let admin = admin_client(&self.db_url).await;
+        admin
+            .batch_execute(&format!(
+                "CREATE TABLE {ns}.{table} (id text PRIMARY KEY, tenant_id text NOT NULL, \
+                 payload jsonb NOT NULL DEFAULT '{{}}'); \
+                 ALTER TABLE {ns}.{table} ENABLE ROW LEVEL SECURITY;"
+            ))
+            .await
+            .expect("out-of-band table");
+    }
+}
+
+async fn admin_client(url: &str) -> tokio_postgres::Client {
+    let (client, conn) = tokio_postgres::connect(url, NoTls)
+        .await
+        .expect("connect admin");
+    tokio::spawn(async move {
+        let _ = conn.await;
+    });
+    client
+}
+
+pub fn request(method: &str, uri: &str, bearer: Option<&str>, body: &[u8]) -> Request<Body> {
+    let mut builder = Request::builder()
+        .method(method)
+        .uri(uri)
+        .header("content-type", "application/json");
+    if let Some(token) = bearer {
+        builder = builder.header("authorization", format!("Bearer {token}"));
+    }
+    builder
+        .body(Body::from(body.to_vec()))
+        .expect("request build")
+}
+
+pub async fn body_json(response: axum::response::Response) -> serde_json::Value {
+    let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
+        .await
+        .expect("body bytes");
+    serde_json::from_slice(&bytes).expect("body is JSON")
+}
+
+/// A minimal tenant-scoped spec body for `ns.table`.
+pub fn spec_body(ns: &str, table: &str) -> String {
+    format!(
+        r#"{{"namespace":"{ns}","tables":[{{"name":"{table}","tenantScoped":true,
+            "columns":[
+              {{"name":"id","type":"text","nullable":false,"primaryKey":true}},
+              {{"name":"payload","type":"jsonb","nullable":false,"default":"'{{}}'"}}
+            ]}}]}}"#
+    )
+}
